package cn.zhuatech.b2b.controller; import cn.zhuatech.b2b.common.ApiResponse; import cn.zhuatech.b2b.dto.B2bDto.*; import cn.zhuatech.b2b.service.B2bService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('BUSINESS_BUYER','ADMIN')") public class BuyerPortalController {private final B2bService service;public BuyerPortalController(B2bService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
